import{_ as t,o as a,c as d,a2 as r}from"./chunks/framework.C9_66ieh.js";const g=JSON.parse('{"title":"Agent frame","description":"","frontmatter":{},"headers":[],"relativePath":"agent-frame.md","filePath":"agent-frame.md","lastUpdated":1785283863000}'),o={name:"agent-frame.md"};function s(n,e,i,l,c,h){return a(),d("div",null,[...e[0]||(e[0]=[r(`<h1 id="agent-frame" tabindex="-1">Agent frame <a class="header-anchor" href="#agent-frame" aria-label="Permalink to &quot;Agent frame&quot;">​</a></h1><p>The <strong>agent frame</strong> is in-terminal TrueDeck chrome around a coding CLI. It reserves a header band (brand, main idea, context) and rewrites CSI so full-screen agent TUIs paint <strong>below</strong> the header instead of overwriting it.</p><p>Implementation: <code>resources/agent-frame/truedeck-frame.mjs</code> Wrap decision: <code>electron/main/agent-frame.ts</code> (called from <code>pty-manager.ts</code>)</p><h2 id="enable-disable" tabindex="-1">Enable / disable <a class="header-anchor" href="#enable-disable" aria-label="Permalink to &quot;Enable / disable&quot;">​</a></h2><p>Settings → <strong>Terminal</strong>:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Effect</th></tr></thead><tbody><tr><td><strong>Agent frame TUI</strong> (<code>agentFrameTui</code>)</td><td><strong>On</strong> (<code>!== false</code>)</td><td>Wrap coding agents in the frame</td></tr><tr><td><strong>Frame shell panes too</strong> (<code>frameShellPanes</code>)</td><td><strong>Off</strong></td><td>Also wrap <code>shell</code> and <code>cmd-*</code> panes</td></tr></tbody></table><p>Notes from the UI:</p><ul><li>Inspired by Grok Build-style TUI chrome</li><li>Full-screen agents may redraw over the header; the frame <strong>repaints every second</strong></li><li><strong>New tabs only</strong> - restart agents after toggling</li></ul><p>If the frame script is missing, TrueDeck logs a warning and spawns the raw CLI.</p><h2 id="spawn-shape" tabindex="-1">Spawn shape <a class="header-anchor" href="#spawn-shape" aria-label="Permalink to &quot;Spawn shape&quot;">​</a></h2><p>When wrapping is active:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node &lt;…&gt;/truedeck-frame.mjs \\</span></span>
<span class="line"><span> --agent &lt;id&gt; \\</span></span>
<span class="line"><span> --name &lt;displayName&gt; \\</span></span>
<span class="line"><span> --color &lt;#hex&gt; \\</span></span>
<span class="line"><span> --cwd &lt;projectRoot&gt; \\</span></span>
<span class="line"><span> -- \\</span></span>
<span class="line"><span> &lt;resolvedCommand&gt; [args…]</span></span></code></pre></div><p>Extra env from the wrapper:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Value</th></tr></thead><tbody><tr><td><code>TRUEDECK_FRAME</code></td><td><code>1</code> (skips double-wrap)</td></tr><tr><td><code>NODE_PATH</code></td><td>TrueDeck <code>node_modules</code> when found (for <code>node-pty</code>)</td></tr></tbody></table><p>The frame script loads <code>node-pty</code> from TrueDeck’s <code>node_modules</code> (several candidate paths).</p><h2 id="header-idea-line" tabindex="-1">Header idea line <a class="header-anchor" href="#header-idea-line" aria-label="Permalink to &quot;Header idea line&quot;">​</a></h2><p>The “main idea” line is resolved in order (refreshed about every 2s):</p><ol><li><code>TRUEDECK_TASK_IDEA</code> / <code>TRUEDECK_TASK_TITLE</code> / <code>TRUEDECK_INTENT</code></li><li><code>TRUEDECK_TASK_FILE</code> (markdown parse)</li><li>Project <code>.truedeck/current-focus.md</code></li></ol><p>Task dispatch writes both task env and <code>current-focus.md</code>. See <a href="./task-board">Task board</a>.</p><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Role</th></tr></thead><tbody><tr><td><code>TRUEDECK_TASK</code></td><td>Task id</td></tr><tr><td><code>TRUEDECK_TASK_FILE</code></td><td>Absolute task markdown path</td></tr><tr><td><code>TRUEDECK_TASK_TITLE</code></td><td>Short title</td></tr><tr><td><code>TRUEDECK_TASK_IDEA</code></td><td>Header idea string</td></tr><tr><td><code>TRUEDECK_INTENT</code></td><td>Alternate idea source</td></tr><tr><td><code>TRUEDECK_PROJECT</code></td><td>Project root / cwd context</td></tr><tr><td><code>TRUEDECK_FRAME_HEADER</code></td><td>Header height (default <strong>4</strong>, clamped 4-5)</td></tr><tr><td><code>TRUEDECK_MEMORY</code></td><td>Memory mode flag from inject</td></tr><tr><td><code>TRUEDECK_AGENT</code></td><td>Agent id</td></tr><tr><td><code>TRUEDECK_FRAME</code></td><td>Set when already framed</td></tr></tbody></table><h2 id="manual-usage-debug" tabindex="-1">Manual usage (debug) <a class="header-anchor" href="#manual-usage-debug" aria-label="Permalink to &quot;Manual usage (debug)&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resources/agent-frame/truedeck-frame.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --agent</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Codex</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --color</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> #34d399 -- -- codex</span></span></code></pre></div><p>Requires <code>node-pty</code> resolvable from the script’s search path (run from a TrueDeck checkout with <code>npm install</code>).</p><h2 id="brand-marks" tabindex="-1">Brand marks <a class="header-anchor" href="#brand-marks" aria-label="Permalink to &quot;Brand marks&quot;">​</a></h2><p>Built-in brands (mark + ANSI color) include Grok, Codex, Cursor, Claude, Gemini, Shell, Aider, OpenCode. Unknown agents get a generic mark and truncated label.</p><h2 id="csi-offset-behavior" tabindex="-1">CSI offset behavior <a class="header-anchor" href="#csi-offset-behavior" aria-label="Permalink to &quot;CSI offset behavior&quot;">​</a></h2><p>Child PTY output is rewritten so absolute cursor / scroll / clear sequences land below the reserved header rows. Without this, agent TUIs clear the whole screen and erase TrueDeck chrome.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Fix</th></tr></thead><tbody><tr><td>No header</td><td>Settings: enable Agent frame TUI; open a <strong>new</strong> agent tab</td></tr><tr><td>Garbled layout</td><td>Resize window; ensure <code>TERM=xterm-256color</code> (TrueDeck sets this); try toggling frame off for that CLI</td></tr><tr><td><code>node-pty not found</code></td><td>Run from installed TrueDeck / repo with <code>node_modules</code>; packaged builds include agent-frame resources</td></tr><tr><td>Shell has no frame</td><td>Expected unless <strong>Frame shell panes too</strong> is on</td></tr></tbody></table><p>More: <a href="./troubleshooting">Troubleshooting</a>.</p>`,31)])])}const m=t(o,[["render",s]]);export{g as __pageData,m as default};
